package cn.courselens;
import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.io.*;import java.time.Duration;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.android.controller.ActivityController;import static org.junit.Assert.*;import static org.robolectric.util.ReflectionHelpers.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class AiConversationStyleTest {
 @Test public void rolesStayDistinctAndComposerChangesOnlyWithKeyboard()throws Exception{
  for(String variant:new String[]{"light","dark","large"}){RuntimeEnvironment.setQualifiers(variant.equals("large")?"w320dp-h700dp-notnight":"w400dp-h850dp-"+(variant.equals("dark")?"night":"notnight"));RuntimeEnvironment.setFontScale(variant.equals("large")?1.6f:1f);
   try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){
    MainActivity a=c.get();callInstanceMethod(a,"aiAssistant");View page=getField(a,"root");LinearLayout history=page.findViewWithTag("ai-history");history.removeAllViews();
    TextView user=callInstanceMethod(a,"aiMessage",ClassParameter.from(LinearLayout.class,history),ClassParameter.from(String.class,"考试放在对应的时间位置，不单独占一行；和课程重叠时，也要能看清。"),ClassParameter.from(boolean.class,true));
    TextView answer=callInstanceMethod(a,"aiMessage",ClassParameter.from(LinearLayout.class,history),ClassParameter.from(String.class,"# 考试与课表安排\n\n## 按真实时间显示\n考试会放在对应日期和时间的位置，与重叠课程并排显示。**结束时间未知**时会明确标注，不猜测考试时长。\n\n### 保存前核对\n- 核对名称、日期和考试地点。\n- 保留已有课程和聊天内容。\n\n例如开始时间是 `09:00`。"),ClassParameter.from(boolean.class,false));
    assertTrue(user.getBackground() instanceof GradientDrawable);assertNull(answer.getBackground());assertEquals(-1,answer.getLayoutParams().width);EditText input=page.findViewWithTag("ai-message");input.setText("Draft stays here");input.setSelection(5);View composer=page.findViewWithTag("ai-composer");View content=a.findViewById(android.R.id.content);layout(content,a);int compact=composer.getHeight();assertEquals(1,input.getLineCount());assertTrue(input.getHeight()>=input.getLineHeight()+input.getPaddingTop()+input.getPaddingBottom());assertEquals(View.GONE,page.findViewWithTag("ai-strength").getVisibility());assertTrue(page.findViewWithTag("ai-top-fade").getHeight()>page.findViewWithTag("ai-menu").getHeight());capture(content,variant+"-compact");ScrollView conversation=page.findViewWithTag("ai-conversation-scroll");assertFalse(conversation.getClipToPadding());assertEquals(((View)conversation.getParent()).getHeight(),conversation.getHeight());int[] fade=((GradientDrawable)page.findViewWithTag("ai-top-fade").getBackground()).getColors();assertTrue(Color.alpha(fade[0])<255);assertTrue(Color.alpha(fade[1])<Color.alpha(fade[0]));assertEquals(0,Color.alpha(fade[2]));conversation.scrollTo(0,120);capture(content,variant+"-scrolled");conversation.scrollTo(0,0);
    callInstanceMethod(a,"aiComposerExpanded",ClassParameter.from(boolean.class,true));layout(content,a);assertTrue(composer.getHeight()>compact);assertEquals(View.VISIBLE,page.findViewWithTag("ai-strength").getVisibility());capture(content,variant+"-expanded");callInstanceMethod(a,"aiComposerExpanded",ClassParameter.from(boolean.class,false));layout(content,a);assertEquals(compact,composer.getHeight());assertEquals("Draft stays here",input.getText().toString());assertEquals(5,input.getSelectionStart());assertFalse(page.findViewWithTag("ai-top-fade").isClickable());
   }
  }
 }
 private void layout(View view,MainActivity a){org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(Duration.ofMillis(600));android.util.DisplayMetrics dm=a.getResources().getDisplayMetrics();for(int i=0;i<3;i++){view.measure(View.MeasureSpec.makeMeasureSpec(dm.widthPixels,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(dm.heightPixels,View.MeasureSpec.EXACTLY));view.layout(0,0,dm.widthPixels,dm.heightPixels);}}
 private void capture(View view,String name)throws Exception{File dir=new File(System.getProperty("user.home"),".codex/morrow-ui-previews/conversation");dir.mkdirs();Bitmap bitmap=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.draw(new Canvas(bitmap));try(FileOutputStream output=new FileOutputStream(new File(dir,name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,output);}bitmap.recycle();}
}
